#!/bin/sh
# layer-2 load audit -- ruby -- generated by
# Research/data_representation/audit_generate.py . Do not hand-edit; regenerate.
# Every line of /out/l2_ruby.txt is FACT_ID|RESULT, FACT_ID being
# <form>.<representation>.<probe>.
set -u
ROOT=/work/l2_ruby
rm -rf "$ROOT"; mkdir -p "$ROOT"
export HOME=/work
export GOFLAGS=-mod=mod
export GO111MODULE=off
export GOCACHE=/work/.gocache
export GOPATH=/work/.gopath
export PATH=/persist/dart-sdk/bin:$PATH

# swift's binaries want an ncurses name the image does not ship under; the fix
# is per-container, so every script that may touch swift re-applies it.
ncurses_fix() {
  if [ -f /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 ]; then
    ln -sf /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 \
       /usr/lib/x86_64-linux-gnu/libncurses.so.6 2>/dev/null
    ldconfig 2>/dev/null
  fi
}
ncurses_fix

OUT=/out/l2_ruby.txt
: > "$OUT"
echo "=== layer-2 load audit -- ruby ==="
date -u +%Y-%m-%dT%H:%M:%SZ
if ! command -v ruby >/dev/null 2>&1; then
  echo "ruby: TOOLCHAIN ABSENT -- nothing run"
  echo "__ABSENT__|<absent>" >> "$OUT"
  exit 0
fi


# ---- cell nothing.NilClass (1 probes)
D=$ROOT/nothing_NilClass; mkdir -p "$D"; cd "$D"
cat > main.rb <<'L2_SRC_EOF'

def _p0()
  v = nil
  return (v.inspect)
end
begin
  puts("nothing.NilClass.null|" + _p0().to_s)
rescue Exception => e
  puts("nothing.NilClass.null|<error:" + e.class.to_s + ">")
end
$stdout.flush
L2_SRC_EOF
if timeout 60 ruby main.rb > run.out 2> run.err; then :; else
  echo "nothing.NilClass: run ended early ($(grep -c "|" run.out) lines printed)"
  sed -n 1,6p run.err
fi
grep "|" run.out >> "$OUT"
grep -qF "nothing.NilClass.null|" run.out || echo "nothing.NilClass.null|<no-output>" >> "$OUT"

